INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 1, 1.5, 0.029, 1, 110, 160, 101, 1, 122601, 105, 1, 0, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 2, 2.5, 0.014, 2, 105, 120, 102, 0, 122401, 111, 3, 1, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 3, 2.5, 0.017, 3, 110, 350, 103, 0, 122501, 105, 2, 0, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 4, 1.5, 0.016, 4, 110, 130, 104, 0, 107501, 105, 3, 1, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 5, 2.5, 0.014, 5, 110, 160, 105, 1, 107601, 105, 1, 0, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 6, 3.5, 0.029, 6, 120, 255, 106, 0, 107801, 103, 2, 0, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 7, 3.5, 0.013, 7, 120, 160, 107, 1, 110601, 103, 1, 0, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 8, 2.5, 0.014, 8, 110, 350, 108, 0, 110401, 103, 2, 0, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 9, 1.5, 0.012, 9, 105, 130, 109, 0, 110501, 100, 3, 1, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 10, 2.5, 0.014, 10, 105, 200, 110, 1, 115701, 103, 1, 0, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 11, 2.5, 0.071, 11, 105, 350, 111, 0, 113601, 103, 2, 0, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 12, 1.5, 0.014, 12, 120, 130, 112, 0, 107901, 103, 3, 1, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 13, 1.5, 0.022, 13, 110, 200, 113, 1, 108001, 105, 2, 0, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 14, 2.5, 0.031, 14, 110, 160, 114, 1, 110301, 108, 1, 0, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 15, 0.5, 0.036, 15, 110, 130, 115, 0, 107701, 105, 1, 1, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 16, 3.5, 0.048, 16, 110, 350, 116, 0, 113101, 95, 2, 0, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 17, 1.5, 0.043, 17, 105, 130, 117, 0, 113301, 105, 3, 1, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 18, 1.5, 0.018, 18, 105, 130, 118, 0, 113201, 95, 2, 1, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 19, 2.5, 0.021, 19, 110, 160, 119, 1, 117001, 108, 2, 0, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 20, 2.5, 0.036, 20, 110, 255, 120, 0, 113501, 105, 1, 0, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 21, 2.5, 0.02, 21, 105, 350, 121, 0, 113401, 105, 3, 0, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 22, 2.5, 0.018, 22, 110, 130, 122, 0, 110101, 105, 1, 1, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 23, 3.5, 0.03, 23, 105, 160, 123, 1, 110001, 111, 3, 0, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 24, 1.5, 0.027, 24, 110, 130, 124, 0, 117201, 103, 1, 1, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 25, 3.5, 0.02, 25, 105, 160, 125, 1, 117301, 108, 2, 0, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 26, 2.5, 0.04, 26, 110, 350, 126, 0, 117401, 105, 3, 0, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 27, 3.5, 0.009, 27, 110, 350, 127, 0, 117101, 105, 1, 0, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 28, 3.5, 0.022, 28, 120, 255, 128, 0, 122901, 105, 1, 0, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 29, 2.5, 0.028, 29, 110, 130, 129, 0, 122801, 105, 3, 1, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？");
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 30, 3.5, 0.023, 30, 105, 130, 130, 1, 122701, 108, 2, 0, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。");
